using System;using System.IO;using System.Text;using System.Security.Cryptography;using System.Runtime.Serialization.Json;using System.Threading;
namespace DeepSeekFloat {
 internal static class SignedFeedTests {
  static int passed;static RSACryptoServiceProvider rsa;static string root;static long now;
  static byte[] Json<T>(T value){using(var s=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(s,value);return s.ToArray();}}
  static void Check(bool ok,string name){if(!ok)throw new Exception(name);passed++;Console.WriteLine("PASS "+name);}
  static void Reject(Action call,string name){bool failed=false;try{call();}catch(Exception){failed=true;}Check(failed,name);}
  static UpdateRelease Release(string version="1.0.21"){return new UpdateRelease{tag_name="v"+version,body="fixture",assets=new[]{new UpdateAsset{name="DeepSeek-Reflex-"+version+"-Windows-x64.zip",size=123,digest="sha256:"+new string('a',64),browser_download_url=SignedUpdateFeed.Root+"releases/"+version+"/DeepSeek-Reflex-"+version+"-Windows-x64.zip"}}};}
  static byte[] Envelope(byte[] payload){return Json(new UpdateEnvelope{payload=Convert.ToBase64String(payload),signature=Convert.ToBase64String(rsa.SignData(payload,CryptoConfig.MapNameToOID("SHA256")))});}
  static SignedUpdateDocument Doc(){return new SignedUpdateDocument{schema=1,issued=now-60,expires=now+86400,release=Release()};}
  static SignedUpdateDocument Parse(byte[] bytes){return SignedUpdateFeed.Parse(bytes,rsa.ToXmlString(false),DateTime.UtcNow);}
  static void MainTest() {
   var valid=Envelope(Json(Doc()));Check(Parse(valid).release.Version==new Version(1,0,21),"signed fixture accepted with exact mirrored release URL");
   using(var wrong=new RSACryptoServiceProvider(2048)){wrong.PersistKeyInCsp=false;Reject(()=>SignedUpdateFeed.Parse(valid,wrong.ToXmlString(false),DateTime.UtcNow),"wrong public key rejected");}
   var outer=new UpdateEnvelope{payload=Convert.ToBase64String(Json(Doc())),signature=Convert.ToBase64String(new byte[256])};Reject(()=>Parse(Json(outer)),"forged signature rejected");outer.signature="!";Reject(()=>Parse(Json(outer)),"malformed base64 rejected");outer.signature=Convert.ToBase64String(new byte[257]);Reject(()=>Parse(Json(outer)),"oversize signature rejected");
   Reject(()=>Parse(new byte[1024*1024+1]),"envelope bound enforced");Reject(()=>Parse(Encoding.UTF8.GetBytes("null")),"null envelope rejected");
   string text=Encoding.UTF8.GetString(valid);text=text.Insert(1,"\"payload\":\"AA==\",");Reject(()=>Parse(Encoding.UTF8.GetBytes(text)),"duplicate outer member rejected");
   string inner=Encoding.UTF8.GetString(Json(Doc())).Replace("\"schema\":1","\"schema\":1,\"schema\":1");Reject(()=>Parse(Envelope(Encoding.UTF8.GetBytes(inner))),"duplicate signed payload member rejected");
   var bad=Doc();bad.schema=2;Reject(()=>Parse(Envelope(Json(bad))),"unknown schema rejected");bad=Doc();bad.expires=now-1;Reject(()=>Parse(Envelope(Json(bad))),"expired manifest rejected");bad=Doc();bad.issued=now+600;bad.expires=now+86400;Reject(()=>Parse(Envelope(Json(bad))),"future issue rejected");bad=Doc();bad.expires=bad.issued+31L*86400;Reject(()=>Parse(Envelope(Json(bad))),"overlong lifetime rejected");
   bad=Doc();bad.release.assets[0].browser_download_url="https://example.com/file.zip";Reject(()=>Parse(Envelope(Json(bad))),"signed arbitrary download origin still rejected");bad=Doc();bad.release.assets[0].browser_download_url=SignedUpdateFeed.Root+"releases/1.0.21/../file.zip";Reject(()=>Parse(Envelope(Json(bad))),"signed path mismatch rejected");
   bad=Doc();bad.release.assets[0].size=UpdateFeed.MaxDownload+1;Reject(()=>Parse(Envelope(Json(bad))),"signed package size enforced");bad=Doc();bad.release.assets[0].digest="sha256:bad";Reject(()=>Parse(Envelope(Json(bad))),"signed digest format enforced");bad=Doc();bad.release.prerelease=true;Reject(()=>Parse(Envelope(Json(bad))),"signed prerelease rejected");
   string state=Path.Combine(root,"highest.json");var release=Parse(valid).release;SignedUpdateFeed.Remember(release,state);SignedUpdateFeed.Remember(release,state);Check(File.Exists(state),"same version same digest accepted for renewal");
   var old=Release("1.0.20");UpdateFeed.ValidateRelease(old,true);Reject(()=>SignedUpdateFeed.Remember(old,state),"rollback version rejected");var changed=Parse(valid).release;changed.Asset.digest="sha256:"+new string('b',64);Reject(()=>SignedUpdateFeed.Remember(changed,state),"same version different digest rejected");
   var renewal=Doc();renewal.issued=now;renewal.expires=now+2*86400;var renewed=Parse(Envelope(Json(renewal)));SignedUpdateFeed.Remember(renewed.release,state);Check(renewed.issued>Doc().issued,"fresh same-artifact renewal succeeds after expiry fixture rejection");
   string denied=Path.Combine(root,"denied.json");Directory.CreateDirectory(denied);Reject(()=>SignedUpdateFeed.Remember(release,denied),"unwritable replay state fails closed");File.WriteAllText(state,"bad json");Reject(()=>SignedUpdateFeed.Remember(release,state),"corrupt replay state fails closed");
   UpdateFeed.ValidateUri(new Uri(SignedUpdateFeed.Latest));Reject(()=>UpdateFeed.ValidateUri(new Uri("https://test.doitbenai.cloud/other")),"same host unrelated route rejected");Reject(()=>UpdateFeed.ValidateUri(new Uri("http://test.doitbenai.cloud/reflex/updates/stable.json")),"plain HTTP rejected");
  }
  static int Main(string[] args){root=args[0];Directory.CreateDirectory(root);try{if(args.Length>1&&args[1]=="--live"){var r=UpdateFeed.Check(CancellationToken.None);Console.WriteLine("PASS live signed source "+r.tag_name);string file=Path.Combine(root,"official.zip");UpdateFeed.Download(r,file,CancellationToken.None,null);UpdatePackage.Extract(file,Path.Combine(root,"verified"),r.Version,r.Asset.digest.Substring(7));Console.WriteLine("PASS real mirrored package SHA/allowlist/branding "+r.Version);using(var c=new UpdateCoordinator(()=>System.Threading.Tasks.Task.FromResult<string>(null),v=>{},()=>{},current:new Version(1,0,20),stateFile:Path.Combine(root,"comparison-state.json"),cacheRoot:Path.Combine(root,"comparison-cache"))){c.CheckAsync().GetAwaiter().GetResult();Check(c.State==UpdateStatus.Available&&c.Release.Version==r.Version,"isolated previous-version coordinator offers actual signed release");}return 0;}using(rsa=new RSACryptoServiceProvider(2048)){rsa.PersistKeyInCsp=false;now=(long)(DateTime.UtcNow-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds;MainTest();}Console.WriteLine("TOTAL "+passed+" signed-feed boundary checks");return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
 }
}
